-- ============================================================
-- SEED: Módulo 8 — Past Perfect (A2)
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'past-perfect';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo past-perfect não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 1: had + past participle formation
  (cid,1,1,'gap_fill','By the time the results were published, the team ___ (collect) data for two years.','had collected',NULL,'Past perfect: had + past participle. Shows action completed before another past event.','easy'),
  (cid,1,2,'gap_fill','She ___ (never/study) linguistics before she enrolled in the course.','had never studied',NULL,'Had + never + past participle for negative past perfect.','easy'),
  (cid,1,3,'multiple_choice','Choose the correct form: "Before the lecture began, the professor ___ the slides."','had prepared','["has prepared","prepared","had prepared","was preparing"]','Past perfect = action completed before another past action.','easy'),
  (cid,1,4,'gap_fill','They ___ (not/finish) the experiment when the power went out.','hadn''t finished',NULL,'Hadn''t + past participle for negative past perfect.','easy'),
  (cid,1,5,'gap_fill','He ___ (already/read) the article before the seminar started.','had already read',NULL,'Had + already + past participle for past perfect.','easy'),
  (cid,1,6,'multiple_choice','Which sentence uses Past Perfect correctly?','The researchers had identified the problem before developing a solution.','["The researchers identified the problem before developing a solution (past simple — acceptable if sequence clear).","The researchers had identified the problem before developing a solution.","The researchers have identified the problem before developing a solution.","The researchers identifying the problem before developing a solution."]','Had + past participle for the earlier of two past events.','medium'),
  (cid,1,7,'gap_fill','By 2015, scientists ___ (prove) that the drug was effective.','had proved',NULL,'By + year = deadline in the past → past perfect for what was completed by that time.','medium'),

  -- BLOCK 2: before/after - narrative sequence
  (cid,2,8,'gap_fill','After she ___ (complete) her undergraduate degree, she applied for a master''s program.','had completed',NULL,'"After + past perfect" shows the first action in a sequence.','medium'),
  (cid,2,9,'multiple_choice','Choose the correct sentence about sequence.','Before the team analyzed the data, they had collected samples for six months.','["Before the team analyzed the data, they collected samples for six months (both past simple — OK if clear).","Before the team analyzed the data, they had collected samples for six months.","Before the team had analyzed the data, they collected samples for six months.","Before the team analyzes the data, they had collected samples for six months."]','Past perfect for the earlier action; past simple for the later action.','medium'),
  (cid,2,10,'gap_fill','He submitted the report after he ___ (revise) it three times.','had revised',NULL,'"After + past perfect" for action completed before the next past event.','medium'),
  (cid,2,11,'multiple_choice','Which sentence correctly shows sequence with "before"?','Before the conference started, the organizers had sent all participants the agenda.','["Before the conference started, the organizers sent all participants the agenda (both simple).","Before the conference started, the organizers had sent all participants the agenda.","Before the conference has started, the organizers had sent the agenda.","Before the conference had started, the organizers send the agenda."]','Had + past participle for action completed before a past reference point.','medium'),
  (cid,2,12,'gap_fill','The students felt prepared because they ___ (study) the material thoroughly.','had studied',NULL,'Had studied explains why they felt prepared — earlier cause.','medium'),
  (cid,2,13,'multiple_choice','Choose the correct sequence marker: "She ___ already ___ her methodology when the professor suggested changes."','had / finalized','["has / finalized","had / finalized","was / finalizing","did / finalize"]','Had + already + past participle = past perfect with "already".','hard'),
  (cid,2,14,'gap_fill','By the time we arrived at the conference, the keynote speaker ___ (start) her presentation.','had started',NULL,'"By the time" + past simple → main clause in past perfect.','medium'),

  -- BLOCK 3: when/by the time
  (cid,3,15,'gap_fill','When the committee reviewed the proposal, the authors ___ (address) all previous concerns.','had addressed',NULL,'"When + past simple" → earlier event = past perfect.','medium'),
  (cid,3,16,'multiple_choice','Choose the correct sentence with "when".','When I arrived at the lab, the experiment had already begun.','["When I arrived at the lab, the experiment already began.","When I arrived at the lab, the experiment had already begun.","When I had arrived at the lab, the experiment already began.","When I arrive at the lab, the experiment had already begun."]','Had + already + past participle for event before arrival.','medium'),
  (cid,3,17,'gap_fill','By the time the study was published, the data ___ (be) analyzed three times.','had been',NULL,'"By the time + past simple" → earlier completed event = past perfect.','hard'),
  (cid,3,18,'multiple_choice','Which sentence uses "by the time" correctly?','By the time he got his PhD, he had published 10 papers.','["By the time he got his PhD, he published 10 papers.","By the time he got his PhD, he had published 10 papers.","By the time he gets his PhD, he had published 10 papers.","By the time he got his PhD, he has published 10 papers."]','By the time + past simple → had + past participle.','medium'),
  (cid,3,19,'gap_fill','When researchers reviewed the data, they realized they ___ (make) a significant calculation error.','had made',NULL,'Realized (later) what had happened before (earlier) → past perfect.','medium'),
  (cid,3,20,'multiple_choice','Choose the sentence where both tenses are correct.','By the time the semester ended, they had completed all required coursework.','["By the time the semester ends, they had completed all coursework.","By the time the semester ended, they had completed all required coursework.","By the time the semester has ended, they completed all coursework.","By the time the semester ended, they have completed all coursework."]','By the time + past simple, had + past participle.','medium'),
  (cid,3,21,'gap_fill','The professor was surprised because she ___ (not/expect) so many students to attend.','had not expected',NULL,'Had not (hadn''t) + past participle for negative past perfect.','medium'),

  -- BLOCK 4: narrative sequence in academic contexts
  (cid,4,22,'gap_fill','Darwin ___ (observe) finches in the Galápagos before he formulated his theory of natural selection.','had observed',NULL,'Past perfect for what happened before a key later event.','medium'),
  (cid,4,23,'multiple_choice','Which sentence best describes a research narrative with correct tense sequence?','The team had designed the questionnaire before they recruited participants.','["The team designed the questionnaire before they had recruited participants.","The team had designed the questionnaire before they recruited participants.","The team had designed the questionnaire before they have recruited participants.","The team designed the questionnaire before they recruited participants (both past simple — also acceptable)."]','Past perfect for the first completed action in a research sequence.','hard'),
  (cid,4,24,'gap_fill','By the time the paper was accepted, the authors ___ (revise) it five times.','had revised',NULL,'"By the time + past simple" → past perfect for earlier repeated action.','medium'),
  (cid,4,25,'multiple_choice','Identify the correct sequence: "When Newton observed the apple falling, he ___."','had already been thinking about gravity for years.','["was already thinking about gravity for years.","had already been thinking about gravity for years.","has already been thinking about gravity for years.","is already thinking about gravity for years."]','Past perfect continuous for an action ongoing up to the past moment.','hard'),
  (cid,4,26,'gap_fill','The volcano ___ (erupt) before geologists could warn the nearby population.','had erupted',NULL,'Past perfect for event that happened before another past event.','medium'),
  (cid,4,27,'multiple_choice','Choose the academically appropriate sentence.','By the time the funding was approved, the preliminary data had already been collected.','["By the time the funding was approved, the preliminary data was already collected.","By the time the funding was approved, the preliminary data had already been collected.","By the time the funding has been approved, the data had been collected.","By the time the funding was approved, the data has been collected."]','Had + already + been + past participle (passive past perfect).','hard'),
  (cid,4,28,'gap_fill','The participants ___ (sign) consent forms before the experiment began.','had signed',NULL,'Consent signed before experiment = past perfect.','easy'),

  -- BLOCK 5: contrast with Past Simple
  (cid,5,29,'multiple_choice','Which sentence uses BOTH tenses correctly?','She had written the introduction before her advisor suggested a different approach.','["She wrote the introduction before her advisor had suggested a different approach.","She had written the introduction before her advisor suggested a different approach.","She has written the introduction before her advisor suggested a different approach.","She had wrote the introduction before her advisor suggested a different approach."]','Earlier action = past perfect; later action = past simple.','medium'),
  (cid,5,30,'gap_fill','He ___ (not/eat) anything when he arrived at the symposium, so he was very hungry.','hadn''t eaten',NULL,'Hadn''t eaten = earlier non-action; arrived = later event.','medium'),
  (cid,5,31,'multiple_choice','When is Past Simple preferred over Past Perfect?','When two past actions are clearly sequential without needing to emphasize which came first.','["When actions have no time relationship","When two past actions are clearly sequential without needing to emphasize which came first.","When the action happened just once","When describing future in the past"]','If "before/after" makes sequence clear, past simple can replace past perfect.','hard'),
  (cid,5,32,'gap_fill','After the professor ___ (leave), the students discussed the lecture among themselves.','had left',NULL,'"After + past perfect" for the first of two past events.','medium'),
  (cid,5,33,'multiple_choice','Choose the sentence where Past Perfect is NOT necessary (sequence is already clear).','She finished her homework and then went to bed.','["When I got home, my roommate had already cooked dinner.","She finished her homework and then went to bed.","By the time we arrived, they had left.","He realized he had forgotten his notes."]','"And then" + past simple makes sequence clear — past perfect not required.','hard'),
  (cid,5,34,'gap_fill','The committee rejected the proposal because the researchers ___ (not/include) a budget breakdown.','hadn''t included',NULL,'Past perfect explains why the committee rejected it.','medium'),
  (cid,5,35,'multiple_choice','Identify the error: "After she finished the experiment, she had written the report."','had written should be wrote','["After should be Before","she is correct","had written should be wrote","experiment should be experiments"]','The later action (writing) should be past simple, not past perfect.','hard'),

  -- BLOCK 6: reported speech context
  (cid,6,36,'gap_fill','She said that she ___ (already/submit) the draft before the deadline.','had already submitted',NULL,'In reported speech, past simple backshifts to past perfect.','medium'),
  (cid,6,37,'multiple_choice','Convert to reported speech: He said, "I have finished the analysis."','He said that he had finished the analysis.','["He said that he has finished the analysis.","He said that he finished the analysis.","He said that he had finished the analysis.","He said that he will finish the analysis."]','Present perfect → past perfect in reported speech.','medium'),
  (cid,6,38,'gap_fill','The professor told us that he ___ (design) the course based on the latest research.','had designed',NULL,'"Said that" + past perfect for backshifted past simple in reported speech.','medium'),
  (cid,6,39,'multiple_choice','Change to reported speech: "She explained: ''I read all the articles before writing the literature review.''"','She explained that she had read all the articles before writing the literature review.','["She explained that she reads all the articles.","She explained that she has read all the articles.","She explained that she had read all the articles before writing the literature review.","She explained that she read all the articles."]','Past simple in direct speech → past perfect in reported speech.','hard'),
  (cid,6,40,'gap_fill','The researcher reported that the initial tests ___ (show) promising results.','had shown',NULL,'"Reported that" + past perfect for backshifted past simple.','medium'),
  (cid,6,41,'multiple_choice','Which reported speech sentence is correct?','He claimed that he had conducted the experiment ethically.','["He claimed that he conducted the experiment ethically (also acceptable, no backshift).","He claimed that he has conducted the experiment ethically.","He claimed that he had conducted the experiment ethically.","He claimed that he was conducting the experiment ethically."]','Had + past participle for reported past actions in formal contexts.','hard'),
  (cid,6,42,'gap_fill','She told the committee that she ___ (not/anticipate) the technical difficulties.','hadn''t anticipated',NULL,'Hadn''t + past participle for reported negative past perfect.','medium'),

  -- BLOCK 7: past perfect in academic writing
  (cid,7,43,'gap_fill','Previous studies ___ (establish) a link between stress and poor academic performance before this study confirmed it.','had established',NULL,'Past perfect for what was known before the current research.','hard'),
  (cid,7,44,'multiple_choice','Which sentence correctly uses past perfect in academic writing?','By the time the researchers controlled for confounding variables, they had collected data from 500 participants.','["By the time the researchers controlled for confounding variables, they collected data from 500 participants.","By the time the researchers controlled for confounding variables, they had collected data from 500 participants.","By the time the researchers had controlled for confounding variables, they collected data.","By the time the researchers control for variables, they had collected data."]','Had + past participle for earlier completed research action.','hard'),
  (cid,7,45,'gap_fill','The methodology ___ (not/been/validate) at the time of the initial publication.','had not been validated',NULL,'Passive past perfect: had + not + been + past participle.','hard'),
  (cid,7,46,'multiple_choice','Choose the correct academic sentence.','Darwin had developed the concept of natural selection years before he published "On the Origin of Species."','["Darwin developed the concept of natural selection years before he published his book.","Darwin had developed the concept of natural selection years before he published ''On the Origin of Species.''","Darwin has developed the concept before he published.","Darwin had developed the concept before he was publishing his book."]','Had + past participle for earlier academic/historical event.','medium'),
  (cid,7,47,'gap_fill','By the time the article went through peer review, the authors ___ (revise) the discussion section twice.','had revised',NULL,'"By the time + past simple" → past perfect for earlier revision.','medium'),
  (cid,7,48,'multiple_choice','Identify the correct past perfect sentence in a literature review.','Prior to this study, researchers had largely overlooked the role of epigenetics in aging.','["Prior to this study, researchers largely overlooked the role of epigenetics.","Prior to this study, researchers had largely overlooked the role of epigenetics in aging.","Prior to this study, researchers have largely overlooked the role of epigenetics.","Prior to this study, researchers overlooked largely the role of epigenetics."]','Past perfect for what happened before the current study.','hard'),
  (cid,7,49,'gap_fill','The original hypothesis ___ (be) disproven before the new model was proposed.','had been',NULL,'Passive past perfect: had been + past participle.','hard'),

  -- BLOCK 8: mixed past perfect review
  (cid,8,50,'multiple_choice','Choose the correct sentence.','When the dean arrived, the committee had been waiting for an hour.','["When the dean arrived, the committee was waiting for an hour.","When the dean arrived, the committee had been waiting for an hour.","When the dean had arrived, the committee had been waiting for an hour.","When the dean arrived, the committee has been waiting for an hour."]','Past perfect continuous for action ongoing up to a past moment.','hard'),
  (cid,8,51,'gap_fill','She ___ (never/present) at an international conference before she spoke at Oxford.','had never presented',NULL,'Had never + past participle for past perfect negative experience.','medium'),
  (cid,8,52,'multiple_choice','Identify the error: "Before the results came in, the team have published their hypothesis."','have published should be had published','["Before should be After","results should be result","have published should be had published","hypothesis should be hypotheses"]','Past perfect requires "had", not "have".','medium'),
  (cid,8,53,'gap_fill','He was exhausted because he ___ (work) for 16 hours straight.','had worked',NULL,'Had worked explains the cause of his exhaustion at a past moment.','medium'),
  (cid,8,54,'multiple_choice','Choose the sentence with correct tense sequence.','After the panel had reviewed all submissions, they announced the winner.','["After the panel reviewed all submissions, they have announced the winner.","After the panel had reviewed all submissions, they announced the winner.","After the panel has reviewed all submissions, they announced the winner.","After the panel had reviewed all submissions, they had announced the winner."]','After + past perfect → past simple for the next event.','medium'),
  (cid,8,55,'gap_fill','The data ___ (already/be) corrupted when the technician noticed the error.','had already been',NULL,'Had already been (passive past perfect) for event before another past event.','hard'),
  (cid,8,56,'multiple_choice','Which sentence is grammatically correct?','The students had submitted their papers before the professor extended the deadline.','["The students submitted their papers before the professor had extended the deadline.","The students have submitted their papers before the professor extended the deadline.","The students had submitted their papers before the professor extended the deadline.","The students had submitted their papers before the professor has extended the deadline."]','Earlier action (had submitted) before later action (extended, past simple).','medium'),

  -- BLOCK 9: TOEFL academic contexts
  (cid,9,57,'multiple_choice','[TOEFL Reading] The passage states that by the 19th century, scientists ___ the basic principles of thermodynamics.','had established','["have established","established","had established","were establishing"]','"By the 19th century" = past deadline → past perfect.','medium'),
  (cid,9,58,'gap_fill','[TOEFL Listening] The professor explains: "By the time Watson and Crick published their model, researchers ___ (already/suspect) DNA was helical."','had already suspected',NULL,'"By the time" + past simple → past perfect for earlier suspicion.','hard'),
  (cid,9,59,'multiple_choice','[TOEFL Reading] Choose the correct sentence about historical sequence.','Copernicus had proposed a heliocentric model decades before Galileo confirmed it with telescopic evidence.','["Copernicus proposed a heliocentric model decades before Galileo had confirmed it.","Copernicus had proposed a heliocentric model decades before Galileo confirmed it with telescopic evidence.","Copernicus has proposed a heliocentric model before Galileo confirmed it.","Copernicus had propose a heliocentric model before Galileo confirmed it."]','Earlier historical event = past perfect; later = past simple.','hard'),
  (cid,9,60,'gap_fill','[TOEFL Reading] The economy ___ (already/enter) a recession before the government implemented fiscal stimulus measures.','had already entered',NULL,'"Before + past simple" → past perfect for what had already happened.','hard'),
  (cid,9,61,'multiple_choice','[TOEFL Listening] The professor says the archaeologists were shocked because they ___ "never encountered such well-preserved artifacts."','had never encountered','["never encountered","have never encountered","had never encountered","were never encountering"]','Had never + past participle for past perfect negative in narrative.','hard'),
  (cid,9,62,'gap_fill','[TOEFL Reading] According to the passage, the civilization ___ (develop) advanced writing systems long before contact with other cultures.','had developed',NULL,'Past perfect for early achievement before a later historical event.','hard'),
  (cid,9,63,'multiple_choice','[TOEFL Listening] The professor explains: "The technique was considered revolutionary because nothing like it ___."','had ever been attempted before','["has ever been attempted before","ever was attempted before","had ever been attempted before","was ever attempted before"]','Had + ever + been + past participle = passive past perfect for unprecedented events.','hard'),

  -- BLOCK 10: TOEFL production tasks
  (cid,10,64,'multiple_choice','[TOEFL Reading] Which sentence correctly describes a historical research context?','By the time penicillin was widely available, Fleming had already identified its antibiotic properties decades earlier.','["By the time penicillin was widely available, Fleming identified its properties decades earlier.","By the time penicillin was widely available, Fleming has identified its properties.","By the time penicillin was widely available, Fleming had already identified its antibiotic properties decades earlier.","By the time penicillin will be available, Fleming had identified its properties."]','By the time + past simple → had + already + past participle.','hard'),
  (cid,10,65,'gap_fill','[TOEFL Reading] The author argues that by the time policymakers responded, the situation ___ (deteriorate) beyond a manageable point, and critical infrastructure ___ (collapse) in several regions.','had deteriorated / had collapsed',NULL,'Two sequential past perfect events both preceding the policy response.','hard'),
  (cid,10,66,'multiple_choice','[TOEFL Speaking — 45s] You are describing background events in academic history. Which sentence uses past perfect most effectively?','By the time the 20th century began, industrialization had already transformed the social and economic fabric of Europe, creating conditions that would lead to unprecedented conflict.','["By the time the 20th century began, industrialization transformed Europe.","By the time the 20th century began, industrialization had already transformed the social and economic fabric of Europe, creating conditions that would lead to unprecedented conflict.","By the time the 20th century was beginning, industrialization has transformed Europe.","Industrialization transformed Europe before the 20th century began."]','Had already + past participle for completed earlier historical change.','hard'),
  (cid,10,67,'production','[TOEFL Speaking — 45s] Describe a breakthrough in science or technology using narrative sequence. Include: what researchers had already discovered or established before the breakthrough, what happened at the moment of discovery (past simple), and what changed as a result.','',NULL,'Use past perfect for earlier background events and past simple for the key breakthrough moment.','hard'),
  (cid,10,68,'production','[TOEFL Writing] Write a paragraph (4-5 sentences) about a historical event or scientific discovery. Use past perfect for events that occurred before the main event, past simple for the main sequence, and include at least one "by the time" or "before" structure.','',NULL,'Demonstrate mastery of past perfect for narrative sequencing in academic writing.','hard'),
  (cid,10,69,'multiple_choice','[TOEFL Writing] Which sentence best fits a research methods section describing the sequence of steps?','After the researchers had obtained ethical approval, they recruited participants and began data collection.','["After the researchers obtained ethical approval, they had recruited participants.","After the researchers had obtained ethical approval, they recruited participants and began data collection.","After the researchers have obtained ethical approval, they recruited participants.","After the researchers had obtained ethical approval, they have begun data collection."]','After + past perfect → past simple for sequential research steps.','hard'),
  (cid,10,70,'production','[TOEFL Writing] Write a literature review paragraph (4-5 sentences) describing what researchers had discovered before a pivotal study in your field. Use past perfect for prior knowledge, past simple for the pivotal study, and include a reported speech sentence describing what an earlier researcher claimed.','',NULL,'Integrate past perfect (prior knowledge), past simple (key study), and reported speech in academic prose.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
